llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C01"],
      "claim": "Imatinib, a basic piperazine-containing kinase inhibitor with an ionizable amine and heteroaromatic system, has a measured absolute oral bioavailability of 98% in humans, demonstrating that such physicochemical features do not preclude high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Brepocitinib has an estimated absolute oral bioavailability of 75% in humans, providing direct human evidence that a small-molecule drug can achieve high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "GSK1322322 showed 57% absolute oral bioavailability in the fasted state in healthy volunteers, supporting high F despite absorption and formulation limitations.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Brigatinib had an approximate oral bioavailability of 46% in healthy volunteers, a direct human measurement above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Tacrolimus, the closest retrieved analogue by Morgan similarity, has an oral bioavailability of about 20–25% in patients, which is at or above the threshold and supports high F, though with a narrow margin.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "low",
  "decision_summary": "All retrieved experimental records report absolute oral bioavailability at or above 20% (20–98%), and none support F < 20%. Although Morgan similarities are low and the physicochemical prior is unfavorable, the unanimous high-F direction from human data, including a basic kinase inhibitor (imatinib, 98%) and a borderline macrolide (tacrolimus, 20–25%), makes F ≥ 20% better supported than F < 20%.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement for the query molecule.",
    "Morgan similarity scores are low (0.23–0.38), limiting quantitative transferability.",
    "No direct permeability, efflux, or first-pass metabolism data for the query.",
    "One retrieved record (C06) is a predicted value rather than an experimental measurement.",
    "Tacrolimus F is borderline (20–25%), so small differences could change threshold classification."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

